import React from 'react';
import { useLocation, useParams } from 'react-router-dom';
import HeaderShop from '../../components/E-Commerce/AllProducts/HeaderShop';
import ProductDetail from '../../components/E-Commerce/ProductDetail/ProductDetail';
import Preloader from '../../helper/Preloader';
import FooterOne from '../../components/FooterOne';
import { SimilarProducts } from '../../components/E-Commerce/ProductDetail/SimilarProducts';
import FrequentlyBoughtTogether from '../../components/E-Commerce/ProductDetail/FrequentlyBoughtTogether';
import RatingsReviews from '../../components/E-Commerce/ProductDetail/RatingsReviews';
import FloatingCartBar from '../../components/E-Commerce/FloatingCartBar';

const ProductDetailPage = () => {
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const searchParam = queryParams.get('search') || '';
    const { category, id, category_name, slug_name } = useParams();

    return (
        <>
            <Preloader />
            <HeaderShop initialSearchQuery={searchParam} />
            <ProductDetail categoryName={category || category_name} slugName={id || slug_name} />
            {/* <RatingsReviews />
            <SimilarProducts /> */}
            {/* <FrequentlyBoughtTogether/> */}
            <FooterOne />
            <FloatingCartBar />
        </>
    );
};

export default ProductDetailPage;
